(() => {
  'use strict';
  let api,tab='review',showDone=false;
  let store={done:[],reviewedContent:{},drafts:[],workflows:[
    {id:'welcome',name:'A second invitation',trigger:'First visit',delay:7,channel:'SMS',template:'Hi {first_name}, thank you for joining us. Would you like to come back for another garden shift? Reply if you would like a hand finding a date. Reply STOP to opt out.'},
    {id:'reminder',name:'Before the next shift',trigger:'Upcoming event',delay:1,channel:'Email',template:'Hi {first_name}, a quick reminder about your upcoming community shift. We look forward to seeing you.'},
    {id:'match',name:'An opportunity that fits',trigger:'New opportunity match',delay:0,channel:'Email',template:'Hi {first_name}, we found an opportunity that may fit your interests. We will confirm the details before inviting you to take part.'}
  ]};
  try{const saved=JSON.parse(localStorage.getItem('roots-notices-v1')||'{}');store={...store,...saved};}catch{}
  if(!store.reviewedContent||typeof store.reviewedContent!=='object'||Array.isArray(store.reviewedContent))store.reviewedContent={};
  const e=s=>api.esc(s);
  const demoAvailable=()=>window.RootsBridge?.status?.connected&&window.RootsBridge?.status?.testPreview?.available;
  const preparingDemo=new Set();
  async function reviewDemo(id){
    const draft=store.drafts.find(item=>item.id===id),bridge=window.RootsBridge;
    if(!draft||preparingDemo.has(id))return;
    if(!demoAvailable()){api.toast('Open the connected local workspace to send an example to Roots Demo Inbox.');return;}
    if(!draft.recipients.length||draft.recipients.length>10){api.toast('Choose between 1 and 10 people for this demo.');return;}
    preparingDemo.add(id);
    try{
      await bridge.flush();
      await bridge.loadActivity();
      const saved=(draft.bridgeDraftIds||[]).map(key=>bridge.activity.drafts.find(item=>item.id===key));
      let drafts;
      if(saved.length===draft.recipients.length&&saved.every(Boolean))drafts=saved;
      else{
        const people=api.getState().people;
        if(draft.recipients.some(key=>!people.some(person=>person.id===key)))throw Error('A selected person is no longer in your records. Edit this draft first.');
        const result=await bridge.request('/api/drafts',{method:'POST',headers:{'X-Roots-Test-Token':bridge.status.testPreview.csrfToken},body:JSON.stringify({drafts:draft.recipients.map(key=>({personId:key,channel:draft.channel.toLowerCase(),body:draft.message.replaceAll('{first_name}',people.find(person=>person.id===key).name.split(' ')[0])}))})});
        drafts=result.drafts;draft.bridgeDraftIds=drafts.map(item=>item.id);save(false);
        await bridge.loadActivity();
      }
      window.RootsChat.reviewDrafts(drafts);
    }catch(error){
      if(error.status===403){await bridge.init();api.toast('Connection refreshed. Choose Review demo again to continue.');}
      else api.toast(error.message||'The demo could not be prepared. Your draft is saved.');
    }finally{preparingDemo.delete(id);}
  }
  function save(sync=true){try{localStorage.setItem('roots-notices-v1',JSON.stringify(store));}catch{api.toast('Browser storage unavailable. Changes last for this visit.');}if(sync)window.RootsBridge?.sync();}
  function noticeContent(n){
    const people=api.getState().people;
    return {title:n.title,description:n.description,note:n.note,people:n.people.map(id=>{const p=people.find(person=>person.id===id);return {id,name:p?.name,evidence:n.evidence};}).sort((a,b)=>String(a.id).localeCompare(String(b.id)))};
  }
  function notices(){
    const people=api.getState().people;
    const interested=(person,interest)=>Array.isArray(person.interests)&&person.interests.includes(interest);
    const first=people.filter(p=>p.visits===1),service=people.filter(p=>interested(p,'Service hours'));
    const builders=people.filter(p=>interested(p,'Carpentry')),noConsent=people.filter(p=>p.consent!==true);
    const rows=[
      {id:'return',title:`${first.length} ${first.length===1?'person':'people'} could use a second invitation.`,description:'Each has one recorded visit. A personal invitation to a relevant shift could be a useful next step.',kind:'Engagement',people:first.map(p=>p.id),action:'Review invitation',icon:'message',evidence:'One recorded visit',note:'Visit counts do not tell us whether someone has booked another shift, declined, or wants a message. Check their profile and communication preference before preparing an invitation.'},
      {id:'benefit',title:`Service hours matter to ${service.length} ${service.length===1?'person':'people'}.`,description:'Their stated interests connect with the volunteer placements in Opportunities.',kind:'Opportunity match',people:service.map(p=>p.id),action:'Explore matches',icon:'graduation',evidence:'Service hours interest',note:'This connection comes from the interests saved on these profiles. It is not a confirmed placement. Ask the program about current availability, eligibility, and whether the hours will count before sharing a lead.'},
      {id:'lead',title:'The garden project has a possible starting team.',description:`${builders.length} ${builders.length===1?'person lists':'people list'} carpentry as an interest. That could be a useful conversation for the garden plan.`,kind:'Project readiness',people:builders.map(p=>p.id),action:'Review project',icon:'sprout',evidence:'Carpentry interest',note:'An interest is a starting point, not a verified skill or commitment. The garden project is still a draft plan. Check experience, availability, and who would like to coordinate it before assigning a team.'},
      {id:'consent',title:`${noConsent.length} ${noConsent.length===1?'profile needs':'profiles need'} a communication check.`,description:'SMS permission is not recorded on these profiles, so they stay out of SMS draft audiences.',kind:'People',people:noConsent.map(p=>p.id),action:'Review people',icon:'users',evidence:'SMS permission not recorded',note:'A missing permission record does not mean someone has opted out. Review and update the profile only when you have a valid permission record. Email permission and delivery details need their own check.'}
    ];
    let changed=false;
    const result=rows.map(n=>{
      const signature=JSON.stringify(noticeContent(n));
      if(store.done.includes(n.id)){
        // Keep older reviewed choices; the first observed content becomes their baseline.
        if(typeof store.reviewedContent[n.id]!=='string'){store.reviewedContent[n.id]=signature;changed=true;}
        else if(store.reviewedContent[n.id]!==signature){store.done=store.done.filter(id=>id!==n.id);delete store.reviewedContent[n.id];changed=true;}
      }
      return {...n,status:store.done.includes(n.id)?'Reviewed':'New'};
    }).filter(n=>n.people.length);
    if(changed)save(false);
    return result;
  }
  function refresh(focus){api.render();if(focus)document.querySelector(focus)?.focus({preventScroll:true});}
  function journal(rows,force=false){
    return window.RootsJournal?.review('notices',rows.map(n=>({id:n.id,content:noticeContent(n)})),{force});
  }
  function remoteDrafts(){const grouped=new Set(store.drafts.flatMap(d=>d.bridgeDraftIds||[]));return (window.RootsBridge?.activity?.drafts||[]).filter(d=>!grouped.has(d.id));}
  function tabs(){const draftCount=store.drafts.length+remoteDrafts().length;return `<div class="platform-tabs" role="group" aria-label="Notices view">${[['review','Notes'],['drafts','Drafts'],['workflows','Workflows'],['delivery','Delivery']].map(([key,label])=>`<button data-notice="tab" data-tab="${key}" class="${tab===key?'active':''}" aria-pressed="${tab===key}">${label}${key==='drafts'&&draftCount?` <span>${draftCount}</span>`:''}</button>`).join('')}</div>`;}
  function render(){return `<div class="outreach-workspace">${api.head('Notices','Things worth following up, with the notes behind them.')} ${tabs()}${tab==='review'?review():tab==='workflows'?workflows():tab==='delivery'?delivery():draftList()}</div>`;}
  function noticeMarkup(n,entry){
    const stamp=entry?.updatedAt||entry?.notedAt,changed=entry?.updatedAt&&entry.updatedAt!==entry.notedAt;
    const date=stamp?window.RootsJournal.formatDate(stamp):'Saved';
    const title=stamp?`${changed?'Updated':'Noted'} ${window.RootsJournal.formatStamp(stamp)}`:'From saved records';
    return `<article class="notice-entry"><div class="notice-entry-date">${stamp?`<time datetime="${e(stamp)}" title="${e(title)}">${e(date)}</time>`:e(date)}<span>${n.status==='Reviewed'?'Reviewed':changed?'Updated':'Noted'}</span></div><div class="notice-entry-body"><h2>${e(n.title)}</h2><p class="notice-entry-description">${e(n.description)}</p><div class="notice-entry-bottom"><details class="notice-entry-notes"><summary>Notes &amp; people ${api.icon('chevron-down')}</summary><div class="notice-entry-evidence"><p>${e(n.note)}</p><ul class="notice-evidence-people" aria-label="People behind this finding">${n.people.map(id=>{const p=api.getState().people.find(person=>person.id===id);return p?`<li><button data-notice="person" data-id="${e(p.id)}">${e(p.name)} ${api.icon('arrow')}</button><span>${e(n.evidence)}</span></li>`:'';}).join('')}</ul><button class="text-button notice-reviewed-toggle" data-notice="complete" data-id="${e(n.id)}">${n.status==='Reviewed'?'Return to notes':'Mark reviewed'}</button></div></details><button class="text-button notice-entry-action" data-notice="open" data-id="${e(n.id)}">${e(n.action)} ${api.icon('arrow')}</button></div></div></article>`;
  }
  function review(){
    const all=notices(),reviewed=all.filter(n=>n.status==='Reviewed').length,rows=all.filter(n=>showDone?n.status==='Reviewed':n.status!=='Reviewed'),history=journal(all);
    return `<div class="notice-review-status"><p role="status">${history?.checkedAt?`Records checked <time datetime="${e(history.checkedAt)}">${e(window.RootsJournal.formatStamp(history.checkedAt))}</time>`:'Findings from saved records'}</p><button class="text-button" data-notice="check-records">${api.icon('refresh')} Check records</button></div><div class="notice-feed-filter"><span>${rows.length} ${showDone?'reviewed':rows.length===1?'note to review':'notes to review'}</span><button class="text-button" data-notice="done-filter" aria-pressed="${showDone}">${showDone?'Back to notes':`Reviewed${reviewed?` (${reviewed})`:''}`}</button></div><div class="notice-feed">${rows.map(n=>noticeMarkup(n,history?.entries?.[n.id])).join('')}</div>${!rows.length?`<div class="outreach-empty"><h2>${showDone?'No reviewed notes yet':'Nothing else to review'}</h2><p>${showDone?'Open a note and mark it reviewed when you have followed up.':'Check your saved records again when people or their interests change.'}</p></div>`:''}<p class="platform-footnote notice-feed-footnote">Notes come from the saved demo records. Dates show when Roots first noted or updated a finding in this browser. Checking records does not search the web.</p>`;
  }
  function draftList(){const remote=remoteDrafts(),count=store.drafts.length+remote.length;return `<div class="notice-toolbar"><span class="tiny-label">${count} ${count===1?'draft':'drafts'} · No volunteer messages sent</span><div class="notice-actions">${window.RootsBridge?.status?.connected?'<button class="button quiet" data-notice="refresh-drafts">Refresh</button>':''}<button class="button primary" data-notice="compose">${api.icon('plus')} New draft</button></div></div>${count?`<div class="draft-list">${store.drafts.map(d=>`<article class="draft-row"><div><h3>${e(d.title||d.recipients.map(id=>api.getState().people.find(p=>p.id===id)?.name||'Volunteer').join(', '))}</h3><p class="draft-excerpt">${e(d.message)}</p><small><span class="outreach-channel">${e(d.channel)}</span> · ${d.recipients.length} ${d.recipients.length===1?'recipient':'recipients'} · Not sent</small></div><div class="notice-actions"><button class="button quiet" data-notice="edit-draft" data-id="${e(d.id)}">Edit</button>${demoAvailable()?`<button class="button primary" data-notice="review-demo" data-id="${e(d.id)}">Review demo ${api.icon('arrow')}</button>`:''}</div></article>`).join('')}${remote.map(d=>`<article class="draft-row"><div><h3>${e(d.personName||d.person_name||d.recipient||'Volunteer message')}</h3><p class="draft-excerpt">${e(d.message||d.body||'')}</p><small><span class="outreach-channel">${e(String(d.channel||'Message').toLowerCase()==='sms'?'SMS':String(d.channel||'Message').toLowerCase()==='email'?'Email':'Message')}</span> · Assistant draft · Not sent${d.contactConsent===false?' · Permission not recorded':''}</small></div><button class="button quiet" data-chat="review-draft" data-id="${e(d.id)}">Review in chat ${api.icon('arrow')}</button></article>`).join('')}</div>`:'<div class="outreach-empty"><h2>No drafts yet</h2><p>Create a message here, or ask Roots to prepare one from a person’s profile.</p></div>'}<p class="platform-footnote">Review the people and wording, then send an example to your separate Roots Demo Inbox on Telegram from the connected workspace. SMS and email delivery to volunteers remain unavailable.</p>`;}
  function workflowTiming(w){if(w.delay)return `${w.delay} ${w.delay===1?'day':'days'} ${w.trigger==='Upcoming event'?'before':'later'}`;return w.trigger==='Upcoming event'?'On the event day':w.trigger==='First visit'?'On the first visit':'When matched';}
  function workflows(){return `<div class="workflow-intro"><p>Set an audience, timing, and message. These rules remain drafts.</p><button class="text-button" data-notice="tab" data-tab="delivery">Check delivery ${api.icon('arrow')}</button></div><div class="workflow-list">${store.workflows.map(w=>`<article class="workflow-row"><span class="notice-symbol">${api.icon(w.channel==='SMS'?'message':'refresh')}</span><div><h3>${e(w.name)}</h3><p>${e(w.trigger)} <span>·</span> ${e(workflowTiming(w))} <span>·</span> ${e(w.channel)}</p></div><span class="badge neutral">Draft</span><button class="button quiet" data-notice="workflow" data-id="${e(w.id)}">Configure ${api.icon('arrow')}</button></article>`).join('')}</div><p class="platform-footnote">Audience previews show potential recipients. Delivery, permission, and timing records must be connected before a workflow can run.</p>`;}
  function delivery(){
    const people=api.getState().people.map(person=>{
      const profile=window.RootsPeople?.profileData(person)||{};
      return {...person,...profile,phone:person.phone||profile.phone,email:person.email||profile.email,smsConsentRecorded:person.smsConsentRecorded??profile.smsConsentRecorded,emailConsentRecorded:person.emailConsentRecorded??profile.emailConsentRecorded};
    });
    const recorded=value=>typeof value==='string'&&value.trim().length>0;
    const smsPermission=person=>typeof person.smsConsentRecorded==='boolean'?person.smsConsentRecorded:person.consent===true;
    const channels=[
      {name:'SMS',contact:'Phone recorded',contacts:people.filter(p=>recorded(p.phone)).length,permission:people.filter(smsPermission).length,both:people.filter(p=>recorded(p.phone)&&smsPermission(p)).length},
      {name:'Email',contact:'Email recorded',contacts:people.filter(p=>recorded(p.email)).length,permission:people.filter(p=>p.emailConsentRecorded===true).length,both:people.filter(p=>recorded(p.email)&&p.emailConsentRecorded===true).length}
    ];
    return `<section class="delivery-intro" aria-labelledby="delivery-title"><h2 id="delivery-title">${demoAvailable()?'Examples arrive in Roots Demo Inbox':'Connect Roots Demo Inbox'}</h2><p>${demoAvailable()?'SMS and email examples arrive in a separate Telegram chat, labelled with the intended recipient. Review a saved draft or ask Roots Assistant to send it.':'Connect a separate Roots Demo Inbox bot in the local workspace to receive examples.'} Automatic workflows remain drafts.</p></section><div class="delivery-list">${channels.map(channel=>`<section class="delivery-row" aria-label="${channel.name} readiness"><div class="delivery-channel"><h3>${channel.name}</h3><span class="badge neutral">Not configured</span></div><dl class="delivery-counts"><div><dt>${channel.contact}</dt><dd>${channel.contacts} of ${people.length}</dd></div><div><dt>Permission recorded</dt><dd>${channel.permission} of ${people.length}</dd></div><div><dt>Both recorded</dt><dd>${channel.both} of ${people.length}</dd></div></dl></section>`).join('')}</div><div class="delivery-footer"><p>Counts reflect stored profiles, not verified delivery details. A contact preference does not grant permission. Telegram demo delivery goes only to you; it does not enable volunteer SMS or email.</p><a class="text-button" href="#people">Review people ${api.icon('arrow')}</a></div>`;
  }
  function assistant(){const b=window.RootsBridge,status=b?.status;return `<div class="assistant-intro"><div class="assistant-mark">${api.icon('sprout')}</div><h2>A conversation with your community in view.</h2><p>Ask about a person, find a useful opportunity, or prepare a message. The local test shares its dashboard records with Telegram. The published demo is separate until a hosted connection is added.</p></div><div class="assistant-connection"><div><strong>Roots Assistant on Telegram</strong><p>${status?.telegramErrorCode?'Telegram chat stopped because another bot listener is active.':status?.polling?`Chat with @${e(status.botUsername||'your bot')} in ordinary language. This local test must stay running.`:status?.telegramConfigured?'Bot credentials are configured for the local test.':'Connect a Roots bot to start a conversation in Telegram.'}</p></div><span class="badge ${status?.polling?'green':'neutral'}">${status?.polling?'Listening':status?.telegramConfigured?'Ready to test':'Not connected'}</span></div><div class="assistant-connection"><div><strong>Gemini</strong><p>${status?.geminiConfigured?'A server-side key is configured. Try a question below.':'An API key is needed on the test server. Keys never belong in this page.'}</p></div><span class="badge ${status?.geminiConfigured?'green':'neutral'}">${status?.geminiConfigured?'Configured':'Not connected'}</span></div><p id="assistant-sync-error" class="hint" role="alert">${status?.syncError?`Dashboard sync failed: ${e(status.syncError)}`:''}</p><section class="assistant-test"><h3>Try the assistant</h3><div class="assistant-suggestions">${['Who has only visited once?','Which opportunities fit Maya Chen?','Draft a welcome-back message for Maya.'].map(q=>`<button data-notice="prompt" data-prompt="${e(q)}">${e(q)}</button>`).join('')}</div><form id="assistant-chat-form"><label class="sr-only" for="assistant-prompt">Ask Roots</label><textarea id="assistant-prompt" name="message" rows="2" maxlength="2000" placeholder="Ask Roots about your community…" required></textarea><button class="button primary" type="submit" ${status?.geminiConfigured?'':'disabled'}>Ask Roots ${api.icon('arrow')}</button></form><p class="hint">${status?.geminiConfigured?'This test can read demo records and prepare drafts. Email and SMS delivery are not enabled.':'Open the local test server with your Gemini configuration to try this. The published demo keeps working without a connection.'}</p><div id="assistant-response" class="assistant-response" role="status" aria-live="polite"></div></section>`;}
  function compose(personId,existingId,group,context={}){
    const state=api.getState(),people=state.people,existing=store.drafts.find(d=>d.id===existingId);
    const eventId=existing?.eventId||context.eventId||null,event=eventId?state.events.find(item=>item.id===eventId):null;
    if(eventId&&!event&&!existing){api.toast('This event is no longer in your calendar. Open a current event before drafting an invitation.');return;}
    const selected=(existing?.recipients||group||(personId?[personId]:people.length?[people[0].id]:[])).filter(id=>people.some(person=>person.id===id));
    const channel=existing?.channel||'SMS';
    const eventDate=event?.month&&event?.day?`${event.month} ${event.day}`:event?.date;
    const invitation=event?`Hi {first_name}, would you like to join us for ${event.title}${eventDate?` on ${eventDate}`:''}${event.time?`, ${event.time}`:''}${event.location?` at ${event.location}`:''}? Let us know if you are interested or would prefer another date. Reply STOP to opt out.`:null;
    const message=existing?.message??invitation??'Hi {first_name}, thank you for being part of our community. Would you like to join us for another garden shift? Reply if you would like help finding a date. Reply STOP to opt out.';
    const eventNote=event?`<p class="source-note">For ${e(event.title)}. Confirm current availability and RSVP status before sending an invitation.</p>`:eventId?'<p class="source-note" role="alert">This draft’s event is no longer in your calendar. Its saved message is unchanged; verify the event details before using it.</p>':'';
    api.openDialog('Thoughtful outreach',`<h2 id="dialog-title">${event?'An invitation to '+e(event.title)+'.':selected.length>1?'An invitation to return.':`A message for ${e(people.find(p=>p.id===selected[0])?.name.split(' ')[0]||'a volunteer')}.`}</h2><p class="lead">Make it relevant, make it personal, and save it for review.</p>${eventNote}<form id="notice-draft-form" data-id="${e(existingId||'')}" data-event-id="${e(eventId||'')}"><div class="form-field"><label for="notice-recipients">Recipients</label><select id="notice-recipients" name="recipients" multiple size="${Math.max(1,Math.min(5,people.length))}" required>${people.map(p=>`<option value="${e(p.id)}" ${selected.includes(p.id)?'selected':''}>${e(p.name)}${p.consent?'':' · SMS consent missing'}</option>`).join('')}</select><p class="hint">${demoAvailable()?'Select up to 10 people. Demo delivery goes only to your separate Roots Demo Inbox; missing contact details or permission remain visible for future SMS.':'Select one or more people. SMS drafts exclude people without recorded permission.'}</p></div><div class="form-field"><label for="notice-channel">Channel</label><select id="notice-channel" name="channel"><option ${channel==='SMS'?'selected':''}>SMS</option><option ${channel==='Email'?'selected':''}>Email</option></select></div><div class="form-field"><label for="notice-message">Message</label><textarea name="message" id="notice-message" required maxlength="2000">${e(message)}</textarea><p class="hint">Use {first_name} to personalize each draft.</p></div><button class="button primary wide" type="submit">Save draft</button><p class="source-note">No message is sent. Email permission and delivery details must be verified before sending.</p></form>`);
  }
  function workflow(id){const w=store.workflows.find(x=>x.id===id);api.openDialog('Automated workflow',`<h2 id="dialog-title">${e(w.name)}</h2><p class="lead">Set the rule, then preview who it would reach.</p><form id="workflow-form" data-id="${w.id}"><div class="form-field"><label for="workflow-name">Workflow name</label><input id="workflow-name" name="name" value="${e(w.name)}" required maxlength="80"></div><div class="form-field"><label for="workflow-trigger">When</label><select id="workflow-trigger" name="trigger">${['First visit','Upcoming event','New opportunity match'].map(t=>`<option ${w.trigger===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-row"><div class="form-field"><label for="workflow-delay">Days ${w.trigger==='Upcoming event'?'before':'after'}</label><input id="workflow-delay" name="delay" type="number" min="0" max="90" value="${w.delay}" required></div><div class="form-field"><label for="workflow-channel">Channel</label><select id="workflow-channel" name="channel"><option ${w.channel==='SMS'?'selected':''}>SMS</option><option ${w.channel==='Email'?'selected':''}>Email</option></select></div></div><div class="form-field"><label for="workflow-template">Message template</label><textarea id="workflow-template" name="template" required maxlength="2000">${e(w.template)}</textarea></div><button class="button primary wide" type="submit">Save workflow draft</button></form><section class="dialog-section"><h3>Before it can run automatically</h3><p>Connect an email or SMS delivery provider, verify recipient permission, and confirm event or first-visit timestamps.</p><button class="button wide" data-notice="preview-workflow" data-id="${w.id}">Preview audience</button></section><div id="workflow-preview"></div>`);}
  function previewWorkflow(){
    const form=document.getElementById('workflow-form');
    if(!form.reportValidity())return;
    const values=new FormData(form),trigger=String(values.get('trigger')),channel=String(values.get('channel')),delay=Number(values.get('delay'));
    const state=api.getState(),matched=new Set(window.RootsOpportunities.list().flatMap(o=>o.matches.map(m=>m.personId)));
    const categories=new Set(state.events.map(event=>event.category));
    const rows=state.people.filter(p=>(trigger==='First visit'?p.visits===1:trigger==='New opportunity match'?matched.has(p.id):p.interests.some(interest=>categories.has(interest)))&&(channel!=='SMS'||p.consent));
    const caveat=trigger==='Upcoming event'?'These interests fit an upcoming event; attendance bookings are not recorded.':trigger==='New opportunity match'?'These profiles match an opportunity; newly matched timestamps are not recorded.':'These profiles have one recorded visit; the exact first-visit date still needs verification.';
    document.getElementById('workflow-preview').innerHTML=`<div class="success-panel"><strong>${rows.length} potential recipients · ${e(channel)}</strong>${rows.slice(0,6).map(p=>e(p.name)).join(', ')}${rows.length>6?'…':''}<p>${e(trigger)} · ${delay} ${delay===1?'day':'days'} ${trigger==='Upcoming event'?'before':'after'}. ${caveat} Delivery permission and timing must be verified before activation.</p></div>`;
  }
  window.addEventListener('roots:activity',()=>{if(api&&api.getState().view==='notices'&&tab==='drafts')refresh();});
  window.addEventListener('roots:connection',()=>{const label=document.getElementById('assistant-sync-error');if(label)label.textContent=window.RootsBridge.status?.syncError?`Dashboard sync failed: ${window.RootsBridge.status.syncError}`:'';});
  document.addEventListener('change',event=>{if(event.target.id==='workflow-trigger')document.querySelector('label[for="workflow-delay"]').textContent=event.target.value==='Upcoming event'?'Days before':'Days after';});
  document.addEventListener('click',event=>{const b=event.target.closest('[data-notice]');if(!b||!api)return;const a=b.dataset.notice;if(a==='tab'){tab=b.dataset.tab;refresh(`[data-notice="tab"][data-tab="${tab}"]`);if(tab==='drafts')window.RootsBridge?.loadActivity().catch(error=>api.toast(error.message));}else if(a==='check-records'){journal(notices(),true);refresh('[data-notice="check-records"]');api.toast('Saved records checked.');}else if(a==='done-filter'){showDone=!showDone;refresh('[data-notice="done-filter"]');}else if(a==='person')api.showPerson(b.dataset.id);else if(a==='complete'){const note=notices().find(n=>n.id===b.dataset.id);if(!note)return;if(note.status==='Reviewed'){store.done=store.done.filter(id=>id!==note.id);delete store.reviewedContent[note.id];}else{store.done=[...store.done,note.id];store.reviewedContent[note.id]=JSON.stringify(noticeContent(note));}save();refresh('[data-notice="done-filter"]');api.toast('Notice updated.');}else if(a==='open'){if(b.dataset.id==='return')compose(null,null,api.getState().people.filter(p=>p.visits===1&&p.consent).map(p=>p.id));if(b.dataset.id==='benefit')api.showOpportunity('o05');if(b.dataset.id==='lead')api.showOpportunity('project-garden');if(b.dataset.id==='consent')location.hash='people';}else if(a==='compose')compose();else if(a==='edit-draft')compose(null,b.dataset.id);else if(a==='review-demo'){reviewDemo(b.dataset.id);}else if(a==='workflow')workflow(b.dataset.id);else if(a==='refresh-drafts'){window.RootsBridge.loadActivity().catch(error=>api.toast(error.message));}else if(a==='preview-workflow'){previewWorkflow();}else if(a==='prompt'){document.getElementById('assistant-prompt').value=b.dataset.prompt;document.getElementById('assistant-prompt').focus();}});
  document.addEventListener('submit',async event=>{if(event.target.id==='notice-draft-form'){event.preventDefault();const f=new FormData(event.target),channel=String(f.get('channel')),selected=f.getAll('recipients'),recipients=selected.filter(id=>demoAvailable()||channel!=='SMS'||api.getState().people.find(p=>p.id===id)?.consent),message=String(f.get('message')).trim();if(!recipients.length){api.toast('No recipients have recorded SMS permission. Choose another audience or channel.');return;}if(!message)return;const id=event.target.dataset.id||`draft-${Date.now()}`,draft={id,channel,recipients,message,...(event.target.dataset.eventId?{eventId:event.target.dataset.eventId}:{}),updatedAt:new Date().toISOString()};store.drafts=[draft,...store.drafts.filter(d=>d.id!==id)];save();api.logActivity('An outreach draft saved for review');api.closeDialog();tab='drafts';location.hash='notices';refresh();api.toast(`Draft saved for ${recipients.length} ${recipients.length===1?'person':'people'}. Nothing sent.`);}else if(event.target.id==='workflow-form'){event.preventDefault();const f=new FormData(event.target),w=store.workflows.find(x=>x.id===event.target.dataset.id);Object.assign(w,{name:String(f.get('name')).trim(),trigger:String(f.get('trigger')),delay:Number(f.get('delay')),channel:String(f.get('channel')),template:String(f.get('template')).trim()});save();api.closeDialog();refresh();api.toast('Workflow draft saved. Automatic delivery is not enabled.');}else if(event.target.id==='assistant-chat-form'){event.preventDefault();const input=document.getElementById('assistant-prompt'),response=document.getElementById('assistant-response'),button=event.target.querySelector('button');button.disabled=true;response.textContent='Roots is looking at your community…';try{const result=await window.RootsBridge.chat(input.value);response.textContent=result.reply;await window.RootsBridge.loadActivity();}catch(err){response.textContent=err.message||'The assistant is unavailable. Check the local test connection.';}finally{button.disabled=!window.RootsBridge?.status?.geminiConfigured;}}});
  window.RootsNotices={configure(callbacks){api=callbacks;},render,compose,notices,workflows:()=>store.workflows,drafts:()=>store.drafts,openTab(value){if(value==='assistant'){location.hash='chat';return;}tab=value;location.hash='notices';refresh();if(tab==='drafts')window.RootsBridge?.loadActivity().catch(error=>api.toast(error.message));}};
})();
